const L = params.length;
const s = L / 6;
const bodyMat = { preset: 'metal', color: params.color, metalness: 0.35, roughness: 0.32 };
const darkMat = { preset: 'metal', color: '#252b31', metalness: 0.7, roughness: 0.28 };
const skidMat = { preset: 'metal', color: '#30363b', metalness: 0.75, roughness: 0.3 };
const glassMat = { preset: 'glass', color: '#65b8d3', roughness: 0.08, opacity: 0.82, emissive: '#143b4c', emissiveIntensity: 0.22 };
const accentMat = { preset: 'metal', color: '#f0d35c', metalness: 0.3, roughness: 0.38 };
const lightMat = { preset: 'emissive', color: '#f7fff9', emissive: '#d9fff0', emissiveIntensity: 2.5 };

// Rounded cabin and engine housing; nose points toward +Z.
api.add(api.sphere(1, 2).scale(0.88 * s, 0.78 * s, 1.18 * s).translate(0, 1.42 * s, 0.72 * s), bodyMat);
api.add(api.sphere(1, 2).scale(0.72 * s, 0.58 * s, 0.83 * s).translate(0, 1.67 * s, -0.45 * s), bodyMat);
api.add(api.box(0.62 * s, 0.18 * s, 0.58 * s).translate(0, 2.22 * s, -0.13 * s), darkMat);

// Wraparound front glazing and side windows.
api.add(api.sphere(1, 2).scale(0.7 * s, 0.5 * s, 0.18 * s).translate(0, 1.58 * s, 1.79 * s), glassMat);
api.add(api.sphere(1, 2).scale(0.12 * s, 0.46 * s, 0.62 * s).translate(0.82 * s, 1.6 * s, 0.72 * s), glassMat);
api.add(api.sphere(1, 2).scale(0.12 * s, 0.46 * s, 0.62 * s).translate(-0.82 * s, 1.6 * s, 0.72 * s), glassMat);
api.add(api.box(0.035 * s, 0.82 * s, 0.06 * s).translate(0.835 * s, 1.55 * s, 0.68 * s), darkMat);
api.add(api.box(0.035 * s, 0.82 * s, 0.06 * s).translate(-0.835 * s, 1.55 * s, 0.68 * s), darkMat);

// Tapered tail boom and tail fairing.
api.add(api.cylinder(0.18 * s, 0.43 * s, 2.75 * s, 12).rotate(90, 0, 0).translate(0, 1.67 * s, -1.85 * s), bodyMat);
api.add(api.sphere(0.28 * s, 1).scale(0.8, 0.9, 1.25).translate(0, 1.68 * s, -3.25 * s), bodyMat);
api.add(api.extrude([[0,0],[0.1*s,0],[0.52*s,0.78*s],[0.03*s,0.65*s]],0.11*s).translate(-0.05 * s, 1.72 * s, -3.15 * s), bodyMat);
api.add(api.extrude([[-0.62*s,0],[0.62*s,0],[0.28*s,0.22*s],[-0.28*s,0.22*s]],0.1*s).rotate(90,0,0).translate(0,1.62*s,-2.95*s), bodyMat);

// Skid struts and runners.
for (let side = -1; side <= 1; side += 2) {
  const x = side * 0.72 * s;
  api.add(api.tube([[x,1.05*s,0.68*s],[x*1.2,0.42*s,0.72*s]],0.055*s,8), skidMat);
  api.add(api.tube([[x,1.05*s,-0.35*s],[x*1.2,0.42*s,-0.5*s]],0.055*s,8), skidMat);
  api.add(api.tube([[x*1.2,0.4*s,1.35*s],[x*1.2,0.34*s,0.95*s],[x*1.2,0.34*s,-0.9*s],[x*1.2,0.4*s,-1.2*s]],0.075*s,10), skidMat);
}

// Main rotor mast, hub, and four blades.
api.add(api.cylinder(0.1*s,0.12*s,0.48*s,12).translate(0,2.55*s,-0.12*s), darkMat);
api.add(api.cylinder(0.2*s,0.2*s,0.14*s,12).translate(0,2.82*s,-0.12*s), accentMat);
for (let i = 0; i < 4; i++) {
  api.add(api.box(2.05*s,0.045*s,0.17*s).translate(1.08*s,2.86*s,-0.12*s).rotate(0,i*90,0), darkMat);
}

// Tail rotor on both-visible hub, with four blades in the XY plane.
api.add(api.cylinder(0.1*s,0.1*s,0.42*s,10).rotate(90,0,0).translate(0,1.72*s,-3.53*s), darkMat);
api.add(api.sphere(0.14*s,1).translate(0,1.72*s,-3.76*s), accentMat);
for (let i = 0; i < 4; i++) {
  api.add(api.box(0.11*s,0.78*s,0.045*s).translate(0,2.12*s,-3.78*s).rotate(0,0,i*90), darkMat);
}

// Navigation lights and contrasting belly stripe.
api.add(api.box(0.08*s,0.08*s,1.4*s).translate(0.87*s,1.17*s,0.35*s), accentMat);
api.add(api.box(0.08*s,0.08*s,1.4*s).translate(-0.87*s,1.17*s,0.35*s), accentMat);
api.add(api.sphere(0.07*s,1).translate(0,1.72*s,-3.96*s), lightMat);
api.add(api.sphere(0.065*s,1).translate(0,2.02*s,1.02*s), lightMat);

api.collider({ kind: 'box', halfExtents: [0.9*s,0.75*s,1.25*s], offset: [0,1.45*s,0.55*s] });
api.collider({ kind: 'capsule', radius: 0.3*s, halfHeight: 1.4*s, offset: [0,1.67*s,-1.75*s] });
api.collider({ kind: 'box', halfExtents: [1.0*s,0.12*s,1.35*s], offset: [0,0.36*s,0.05*s] });
return api.build();
